// Split Source Files: one item per uploaded file. Shared intake fields are copied onto every item.
const inItem = $input.first();
const j = (inItem && inItem.json) || {};
const pick = (...keys) => {
  for (const k of keys) {
    if (j[k] !== undefined && j[k] !== null && String(j[k]).trim() !== '') return String(j[k]);
  }
  return '';
};
const shared = {
  project_brief: pick('project_brief', 'Project Brief'),
  sponsor_answers: pick('sponsor_answers', 'Sponsor Answers'),
  question: pick('evidence_question', 'Evidence Question'),
  run_label: pick('run_label', 'Run Label'),
};
const bin = (inItem && inItem.binary) || {};
const out = [];
for (const k of Object.keys(bin)) {
  const b = bin[k];
  const filename = b.fileName || k;
  const m = /\.([A-Za-z0-9]+)$/.exec(filename);
  let ext = m ? m[1].toLowerCase() : '';
  if (!ext) {
    const mt = String(b.mimeType || '').toLowerCase();
    ext = mt.includes('pdf') ? 'pdf' : mt.includes('csv') ? 'csv' : mt.includes('text') ? 'txt' : '';
  }
  out.push({ json: { filename, ext, binary_key: k, ...shared }, binary: { data: b } });
}
if (out.length === 0) {
  return [{ json: { source_index: 0, source_id: 'NONE', filename: '', ext: 'none', note: 'NO_FILES_UPLOADED', ...shared } }];
}
// Stable order so source IDs are reproducible between runs (re-run stability).
out.sort((a, b) => a.json.filename.localeCompare(b.json.filename));
out.forEach((o, i) => {
  o.json.source_index = i + 1;
  o.json.source_id = 'S' + String(i + 1).padStart(2, '0');
});
return out;

// Decode Text or CSV: read the uploaded CSV/TXT bytes as UTF-8 text.
const item = $input.item;
let raw = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer($itemIndex, 'data');
  raw = buf.toString('utf8');
} catch (e) {
  raw = '';
}
return { json: { ...item.json, raw_text: raw } };

// Build Source Record: turn one parsed file into citable units (Page n / Row n / Line n).
const meta = $json.filename !== undefined && $json.source_id !== undefined ? $json : $('Each File').item.json;
const ext = String(meta.ext || '').toLowerCase();
const filename = meta.filename;
const source_id = meta.source_id;
const warnings = [];
const units = [];
let kind = ext;
let loc_max = 0;
let columns = null;

function parseCSV(s) {
  const rows = [];
  let row = [], f = '', q = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (q) {
      if (c === '"') { if (s[i + 1] === '"') { f += '"'; i++; } else q = false; }
      else f += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(f); f = ''; }
    else if (c === '\n') { row.push(f); rows.push(row); row = []; f = ''; }
    else if (c === '\r') { /* skip */ }
    else f += c;
  }
  if (f !== '' || row.length) { row.push(f); rows.push(row); }
  return rows;
}

if (ext === 'none') {
  return { json: { source_id, filename: '(none)', ext, kind: 'none', unit_count: 0, loc_max: 0, units: [], warnings: ['No file was uploaded'] } };
}

if (ext === 'pdf') {
  kind = 'pdf';
  let pages = $json.text;
  if (!Array.isArray(pages)) {
    if (typeof pages === 'string') {
      pages = pages.includes('\f') ? pages.split('\f') : [pages];
      warnings.push('PDF text came back joined; page numbers may be unreliable');
    } else pages = [];
  }
  pages.forEach((p, i) => {
    const t = String(p).replace(/[ \t]+\n/g, '\n').trim();
    units.push({ loc: 'Page ' + (i + 1), n: i + 1, text: t || '(no extractable text on this page)' });
  });
  loc_max = pages.length;
} else if (ext === 'csv') {
  kind = 'csv';
  const text = String($json.raw_text || '').replace(/^﻿/, '');
  const lines = text.split(/\r?\n/);
  let start = 0;
  const comments = [];
  while (start < lines.length && lines[start].trim().replace(/^["']+/, '').startsWith('#')) { comments.push(lines[start].trim()); start++; }
  const rows = parseCSV(lines.slice(start).join('\n'));
  const header = (rows.shift() || []).map((h) => h.trim());
  const data = rows.filter((r) => r.some((c) => String(c).trim() !== ''));
  const compact = data.length > 50; // long tables: column names once in the source header, values only per row
  if (compact) columns = header;
  data.forEach((r, i) => {
    const cell = (ci) => String(r[ci] === undefined ? '' : r[ci]).trim();
    const fields = compact ? header.map((h, ci) => cell(ci)).join(' | ') : header.map((h, ci) => h + ': ' + cell(ci)).join(' | ');
    units.push({ loc: 'Row ' + (i + 1), n: i + 1, id: String(r[0] === undefined ? '' : r[0]).trim(), text: fields });
  });
  loc_max = data.length;
  warnings.push('Row numbers count data rows after the header row');
  if (comments.length) warnings.push('Comment header ignored for row numbering: ' + comments.join(' / '));
} else {
  kind = 'txt';
  const text = String($json.raw_text || '').replace(/^﻿/, '');
  const lines = text.split(/\r?\n/);
  lines.forEach((l, i) => { if (l.trim() !== '') units.push({ loc: 'Line ' + (i + 1), n: i + 1, text: l.trim() }); });
  loc_max = lines.length;
  if (ext !== 'txt') warnings.push('Unrecognised extension "' + ext + '" read as plain text');
}
if (units.length === 0) warnings.push('No readable content found');
return { json: { source_id, filename, ext, kind, unit_count: units.length, loc_max, columns, units, warnings } };

// Build Evidence Pack: one managed set of sources (brief + sponsor answers + every uploaded file).
const records = $input.all().map((i) => i.json).filter((r) => r && r.source_id && Array.isArray(r.units));
records.sort((a, b) => String(a.source_id).localeCompare(String(b.source_id)));
const intake = $('Split Source Files').first().json;
const brief = String(intake.project_brief || '');
const sponsor = String(intake.sponsor_answers || '');

function textSource(label, text) {
  const lines = String(text).split(/\r?\n/);
  const units = [];
  lines.forEach((l, i) => { if (l.trim() !== '') units.push({ loc: 'Line ' + (i + 1), n: i + 1, text: l.trim() }); });
  return { source_id: label, filename: label, ext: 'text', kind: 'text', unit_count: units.length, loc_max: lines.length, units, warnings: [] };
}

const sources = [];
if (brief.trim()) sources.push(textSource('BRIEF', brief));
if (sponsor.trim()) sources.push(textSource('SPONSOR', sponsor));
records.forEach((r) => sources.push(r));

const lines = [];
const flat = [];
const index = [];
const warnings = [];
for (const s of sources) {
  index.push({ source_id: s.source_id, filename: s.filename, kind: s.kind, unit_count: s.unit_count, loc_max: s.loc_max });
  lines.push('=== SOURCE ' + s.source_id + ': ' + s.filename + ' (' + s.kind + ', ' + s.unit_count + ' units) ===');
  if (s.columns) lines.push('COLUMNS (in this order, each row below lists values only): ' + s.columns.join(' | '));
  (s.warnings || []).forEach((w) => warnings.push(s.source_id + ': ' + w));
  for (const u of s.units) {
    const named = s.source_id === 'BRIEF' || s.source_id === 'SPONSOR';
    const tag = named
      ? '[' + s.source_id + ' | ' + u.loc + ']'
      : '[' + s.filename + ' | ' + u.loc + (u.id ? ' | id=' + u.id : '') + ']';
    lines.push(tag + ' ' + u.text);
    flat.push({ src: s.source_id, filename: s.filename, loc: u.loc, id: u.id || '', text: u.text });
  }
  lines.push('');
}
const pack_text = sources.length ? lines.join('\n') : 'INPUT_MISSING';
const source_index_text = index.map((s) => s.source_id + ' | ' + s.filename + ' | ' + s.kind + ' | ' + s.unit_count + ' units (valid locations 1-' + s.loc_max + ')').join('\n');
return [{
  json: {
    pack_text,
    source_index_text: source_index_text || 'NONE',
    source_index: index,
    units: flat,
    question: String(intake.question || ''),
    run_label: String(intake.run_label || ''),
    brief_present: !!brief.trim(),
    sponsor_present: !!sponsor.trim(),
    source_count: sources.length,
    file_count: records.length,
    unit_count: flat.length,
    pack_chars: pack_text.length,
    est_tokens: Math.round(pack_text.length / 4),
    warnings,
  },
}];

const units = $input.first().json.units || [];
const out = []; let cur = null;
for (const u of units) {
  const f = (u.src === 'BRIEF' || u.src === 'SPONSOR') ? u.src : u.filename;
  if (f !== cur) { out.push('=== DOCUMENT: ' + f + ' ==='); cur = f; }
  out.push(u.text);
}
const pack_plain = out.join('\n');
return [{ json: { pack_plain, chars: pack_plain.length, units: units.length } }];

const QS = [["Q01","What is the maximum grant amount?"],["Q02","What is the release condition for Tranche 2?"],["Q03","When is the monthly progress report due to the grant body?"],["Q04","Which cost items are ineligible for the grant?"],["Q05","Who was awarded the design-and-build contract and at what contract sum?"],["Q06","When does Little Harbour Learning plan to open enrolment?"],["Q07","How long must the east core close to replace the two lifts?"],["Q08","What was suspected on level 2 west wing during soft-strip?"],["Q09","Why was the active ageing operator EOI extended?"],["Q10","Who owns the active ageing operator agreement deliverable D14?"],["Q11","Which deliverable was postponed twice?"],["Q12","What does the seed risk register say about hazardous materials?"],["Q13","Which seed risk covers barrier-free access during lift works?"],["Q14","Which resident comment says parents need somewhere to go in the day?"],["Q15","How long did childcare operators need between floor handover and first intake at Seabreeze?"],["Q16","What happened to the grant tranche at Seabreeze when operator agreements were missed?"],["Q17","What is the Tranche 1 payment claim amount in the January contractor report?"],["Q18","What is the asbestos removal estimate in the March contractor report?"],["N01","What colour is the roof garden furniture?"],["N02","Who is the contractor's insurance broker?"],["N03","What is the Wi-Fi password for the Hub?"]];
const items = [];
for (const k of [3, 8]) for (const [id, question] of QS) items.push({ json: { id, question, k } });
return items.slice(30, 42);

