// Parse and Locate Quotes: read each agent JSON, find every quote in the source, score against independent gold.
const units = $('Build Evidence Pack').first().json.units || [];
const meta = $('Retrieve Top-k').all().map((i) => i.json);
const outs = $input.all();
const norm = (s) => String(s || '').toLowerCase().normalize('NFKC').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const fileOf = (u) => (u.src === 'BRIEF' || u.src === 'SPONSOR') ? u.src : u.filename;
const tagOf = (u) => (u.src === 'BRIEF' || u.src === 'SPONSOR') ? '[' + u.src + ' | ' + u.loc + ']' : '[' + u.filename + ' | ' + u.loc + (u.id ? ' | id=' + u.id : '') + ']';
const byFile = {}; units.forEach((u) => { const f = fileOf(u); (byFile[f] = byFile[f] || []).push({ u, n: norm(u.text) }); });
const names = Object.keys(byFile);
const resolve = (f) => names.find((n) => n.toLowerCase() === String(f || '').toLowerCase().trim()) || null;
function locate(file, quote) {
  const q = norm(quote); const f = resolve(file);
  if (q.split(' ').filter(Boolean).length < 3) return { loc: null, why: 'quote too short' };
  if (!f) return { loc: null, why: 'unknown file' };
  const arr = byFile[f]; const hits = [];
  arr.forEach((e) => { if (e.n.includes(q)) hits.push(e.u); });
  if (!hits.length) arr.forEach((e, j) => { if (arr[j + 1] && (e.n + ' ' + arr[j + 1].n).includes(q)) hits.push(e.u); });
  return hits.length ? { loc: tagOf(hits[0]) } : { loc: null, why: 'quote not found' };
}
const FENCE = new RegExp(String.fromCharCode(96, 96, 96) + '(json)?', 'g');
function parse(t) { t = String(t || '').replace(FENCE, ''); const a = t.indexOf('{'), b = t.lastIndexOf('}'); if (a < 0 || b < a) return null; try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { return null; } }
const KEY = { Q01: /10\.2/, Q02: /operator agreement|signed operator|rough-in/i, Q03: /10th working day/i, Q04: /food court|commercial|rooftop|landscap/i, Q05: /Kestrel/i, Q06: /July 2028/i, Q07: /14 weeks/i, Q08: /asbestos/i, Q09: /one response|three|policy|requires at least/i, Q10: /not assigned|unassigned|no owner|blank|none|missing|not (yet )?(been )?(named|set)/i, Q11: /D15|consultation summary/i, Q12: /R08|hazardous/i, Q13: /R11|barrier/i, Q14: /RC002|parents/i, Q15: /7 months|seven months/i, Q16: /4 months|four months/i, Q17: /246,?300/, Q18: /350,?000|0\.35|600,?000/ };
const blank = () => ({ n: 0, answerable: 0, hit: 0, parsed: 0, answered_ok: 0, answerable_notfound: 0, abstain_n: 0, abstain_ok: 0, quotes: 0, verified: 0, chars: 0, errors: 0 });
const summary = { k3: blank(), k8: blank() }; const results = [];
outs.forEach((o, i) => {
  const m = meta[i] || {}; const s = summary['k' + m.k]; if (!s) return; s.n++; s.chars += m.excerpt_chars || 0;
  const j = o.json || {}; const raw = j.text !== undefined ? j.text : (j.output !== undefined ? j.output : ''); const p = parse(raw);
  const rec = { id: m.id, k: m.k, gold_rank: m.gold_rank, status: p ? String(p.status || '') : (j.error ? 'ERROR' : 'UNPARSED'), answer: p ? String(p.answer || '').slice(0, 120) : String(raw || j.error || '').slice(0, 80), cites: [] };
  if (!p) s.errors++; else s.parsed++;
  if (m.has_gold) { s.answerable++; if (m.gold_rank && m.gold_rank <= m.k) s.hit++; if (p && rec.status === 'ANSWERED' && KEY[m.id] && KEY[m.id].test(String(p.answer || ''))) { s.answered_ok++; rec.ok = true; } if (p && rec.status === 'NOT_FOUND') s.answerable_notfound++; }
  else { s.abstain_n++; if (p && rec.status === 'NOT_FOUND') s.abstain_ok++; }
  if (p && Array.isArray(p.citations)) for (const c of p.citations.slice(0, 3)) { const r = locate(c.file, c.quote); s.quotes++; if (r.loc) s.verified++; rec.cites.push(r.loc || ('!' + r.why)); }
  results.push(rec);
});
for (const k of ['k3', 'k8']) summary[k].avg_excerpt_chars = Math.round(summary[k].chars / Math.max(1, summary[k].n));
return [{ json: { summary, results: JSON.stringify(results) } }];

// Retrieve Top-k: BM25 keyword ranking over the citable units; one output item per (question, k).
const pack = $('Build Evidence Pack').first().json;
const units = pack.units || [];
const STOP = new Set(['the','a','an','of','to','in','on','for','and','or','is','are','was','were','be','by','with','what','which','who','when','where','how','does','do','did','it','its','this','that','as','at','from','about','any','there','their','has','have','had','will','would','can','could','should']);
function tok(s) {
  const out = [];
  const words = String(s).toLowerCase().match(/[\p{L}\p{N}][\p{L}\p{N}._-]*/gu) || [];
  for (let w of words) { w = w.replace(/[._-]+$/g, ''); if (w.length > 1 && !STOP.has(w)) out.push(w); }
  return out;
}
function aliasTokens(text) {
  const extra = [];
  for (const m of text.matchAll(/\btranche\s*([1-4])\b/gi)) extra.push('t' + m[1]);
  if (/\bt[1-4]\b/i.test(text)) extra.push('tranche');
  const ALIAS = [[/\beoi\b|expression of interest/i, ['eoi', 'expression', 'interest']], [/\btop\b|temporary occupation permit/i, ['top', 'temporary', 'occupation', 'permit']], [/\bnrf\b|neighbourhood renewal fund/i, ['nrf', 'neighbourhood', 'renewal']], [/\bkhb\b|kestrel harbour/i, ['khb', 'kestrel']], [/\bedc\b|estate development committee/i, ['edc', 'committee']]];
  for (const [re, toks] of ALIAS) if (re.test(text)) extra.push(...toks);
  return extra;
}
const docs = units.map((u) => tok(u.text + ' ' + (u.id || '')));
const N = docs.length || 1; const avgdl = docs.reduce((a, d) => a + d.length, 0) / N || 1;
const df = new Map(); docs.forEach((d) => { new Set(d).forEach((t) => df.set(t, (df.get(t) || 0) + 1)); });
const tagOf = (u) => (u.src === 'BRIEF' || u.src === 'SPONSOR') ? '[' + u.src + ' | ' + u.loc + ']' : '[' + u.filename + ' | ' + u.loc + (u.id ? ' | id=' + u.id : '') + ']';
function rank(q) {
  const qt = [...new Set([...tok(q), ...aliasTokens(q)])]; const sc = [];
  docs.forEach((d, i) => { if (!d.length) return; const tf = new Map(); d.forEach((t) => tf.set(t, (tf.get(t) || 0) + 1)); let s = 0;
    for (const t of qt) { const f = tf.get(t); if (!f) continue; const n = df.get(t) || 0; s += Math.log(1 + (N - n + 0.5) / (n + 0.5)) * ((f * 2.5) / (f + 1.5 * (0.25 + 0.75 * (d.length / avgdl)))); }
    if (s > 0) sc.push({ i, s }); });
  return sc.sort((a, c) => c.s - a.s).map((x) => x.i);
}
const nrm = (s) => String(s || '').toLowerCase().normalize('NFKC').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const GOLD = { Q01: ['07_', 't', 'maximum grant s 10 2 million'], Q02: ['07_', 't', 'completion of structural and m e rough in'], Q03: ['07_', 't', 'monthly progress report is due by the 10th working day'], Q04: ['07_', 't', 'ineligible items include'], Q05: ['01_', 't', 'awarded to kestrel harbour'], Q06: ['01_', 't', 'intends to open enrolment in july 2028'], Q07: ['01_', 't', 'closing the east core for'], Q08: ['01_', 't', 'suspected asbestos containing ceiling boards'], Q09: ['01_', 't', 'one response received'], Q10: ['03_', 'id', 'D14'], Q11: ['03_', 't', 'postponed twice'], Q12: ['04_', 'id', 'R08'], Q13: ['04_', 'id', 'R11'], Q14: ['05_', 'id', 'RC002'], Q15: ['06_', 't', 'needed about 7 months'], Q16: ['06_', 't', 'delayed 4 months'], Q17: ['02_Contractor_progress_report_Jan', 't', 'payment claim 1'], Q18: ['02_Contractor_progress_report_Mar', 't', 'variation asbestos removal'] };
const out = [];
for (const it of $input.all()) {
  const { id, question, k } = it.json; const order = rank(question); const top = order.slice(0, k);
  let gold_rank = null; const g = GOLD[id];
  if (g) { const gi = (u) => String(u.filename).startsWith(g[0]) && (g[1] === 'id' ? u.id === g[2] : nrm(u.text).includes(g[2])); const p = order.findIndex((i) => gi(units[i])); gold_rank = p < 0 ? null : p + 1; }
  const hitIdx = new Set(top); const ctx = [];
  for (const i of top) for (const j of [i - 1, i + 1]) if (j >= 0 && j < units.length && !hitIdx.has(j) && !ctx.includes(j) && units[j].filename === units[i].filename) ctx.push(j);
  ctx.sort((x, y) => x - y);
  const excerpts = top.map((i) => tagOf(units[i]) + ' ' + units[i].text).join('\n') + (ctx.length ? '\nADJACENT LINES:\n' + ctx.map((j) => tagOf(units[j]) + ' ' + units[j].text).join('\n') : '');
  out.push({ json: { id, question, k, gold_rank, has_gold: !!g, excerpts, excerpt_chars: excerpts.length } });
}
return out;
